llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Absolute oral bioavailability of tolfenamic acid was 61.6% in healthy female volunteers after 800 mg oral vs IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C78"],
      "claim": "Absolute oral bioavailability of metoclopramide was 84.5 ± 15.3% in healthy volunteers after oral vs IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Absolute oral bioavailability of nifedipine was 0.43 ± 0.14 after 30 mg oral tablets vs IV, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All 10 evidence molecules, after collapsing repeated reports, have numeric absolute or systemic bioavailability values above 20% in ordinary conditions, mostly 43-100%; assay-transfer scores are high, so the prediction is high.",
  "evidence_gaps": [
    "Molecule 2 contains records for different compounds (brigatinib and GSK1322322); inconsistent cards were discounted, leaving one supporting record.",
    "Some records for atazanavir and metoclopramide use qualitative 'low' or 'poor' language without threshold-relevant numeric values; these were not used as affirmative low-bioavailability evidence.",
    "Several records were obtained under altered conditions (fed state, cirrhosis, elderly) and were not used for direction; ordinary-condition healthy-volunteer absolute bioavailability records were preferred."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

